    internal void RunQuickTab(WindowsShortcut tab){
        string target=tab.Target??"";
        if(target.StartsWith("glass:",StringComparison.OrdinalIgnoreCase)){
            switch(target[6..].Trim().ToLowerInvariant()){
                case "home":ShowHome();break;case "apps":ShowWorkspace("apps");break;case "games":ShowWorkspace("games");break;
                case "projects":ShowWorkspace("projects");break;case "documents":ShowWorkspace("documents");break;case "workspace":ShowWorkspace();break;
                case "note":OpenNotes();break;case "focus":OpenFocus();break;case "settings":Settings();break;
                case "tools":OpenTools();break;case "capture":OpenCapture();break;case "text":OpenCapture(textOnly:true);break;
                case "clipboard":OpenClipboard();break;case "audio":OpenAudio();break;case "workspaces":OpenWorkspaces();break;
                case "files":OpenLargeFiles();break;case "help":OpenHelp();break;case "pin":ToggleAlwaysOnTop();break;case "memo":OpenMemo();break;
                case "controls":ToggleControls();break;case "pc":TogglePc();break;case "palette":TogglePalette();break;
                default:Message("Cet onglet rapide pointe vers une vue inconnue.\n"+target);break;
            }
            return;
        }
        LaunchWindowsShortcut(tab);
    }
