    bool desktopIconsManaged;
    // Le Bureau d'Explorer se publie après le démarrage : un appel unique arrivait trop tôt,
    // rendait la main sans erreur, et les icônes restaient visibles pour toute la session.
    void HideDesktopIcons(){
        if(preview)return;
        int attempt=0;
        void Apply(){
            try{
                Native.Desktop(true);
                desktopIconsManaged=true;
                if(attempt==0)Store.Log("Icônes du Bureau masquées.");
            }catch(Exception ex){
                attempt++;
                if(attempt<4){
                    Store.Log("Masquage du Bureau, nouvel essai: "+ex.Message);
                    var retry=new DispatcherTimer{Interval=TimeSpan.FromSeconds(attempt==1?1:2)};
                    retry.Tick+=(_,_)=>{retry.Stop();Apply();};
                    retry.Start();
                }else Store.Log("Masquage du Bureau impossible: "+ex.Message);
            }
        }
        Apply();
        foreach(int delay in DesktopReasserts){
            var timer=new DispatcherTimer{Interval=TimeSpan.FromSeconds(delay)};
            timer.Tick+=(_,_)=>{timer.Stop();if(disposed||preview)return;Apply();};
            timer.Start();
        }
    }
    static readonly int[] DesktopReasserts={3,10};
    internal void RestoreDesktopIcons(){if(!desktopIconsManaged)return;try{Native.Desktop(false);desktopIconsManaged=false;Store.Log("Icônes du Bureau rétablies.");}catch(Exception ex){Store.Log("Rétablissement du Bureau: "+ex.Message);}}
